/**
 * Project tokens: the short-lived Supabase JWTs XOS mints itself (ADR 0168, D5). api-token exchanges an API key for one
 * acting as the key's service account, automation-run acts as an automation's owner, and the chat integrations act as
 * the person linked to a chat user. PostgREST verifies the signature against the project's JWT signing keys, and RLS
 * then sees an ordinary member.
 *
 * The signing key is XOS_API_JWT_SIGNING_KEY: a private JWK (EC P-256 for ES256, or RSA for RS256) with its `kid`,
 * generated by `supabase gen signing-key` and imported into the project's JWT signing keys, so the project's key set
 * names it and PostgREST trusts what it signs. Supabase never hands out its own private keys, so a key XOS signs with
 * is always one XOS holds.
 *
 * A shared secret (HS256, the legacy JWT secret's kind) is refused in production. Elsewhere it is still read, because
 * the local CLI stack signs with its well-known development JWT secret.
 *
 * Web Crypto only, so it runs in Deno and in Vitest.
 */

export type ProjectTokenClaims = Readonly<Record<string, unknown>>;

/** Signs one set of claims; what the minting code is given, so it never sees the key. */
export type ProjectTokenSigner = (claims: ProjectTokenClaims) => Promise<string>;

/** Web Crypto's key type, named without the DOM library so every package's typecheck reads it. */
type WebCryptoKey = Awaited<ReturnType<typeof crypto.subtle.importKey>>;

export interface ProjectSigningKey {
  readonly alg: "ES256" | "RS256" | "HS256";
  readonly kid: string | null;
  readonly key: WebCryptoKey;
}

export class ProjectSigningKeyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ProjectSigningKeyError";
  }
}

function base64url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

const encodeJson = (value: unknown) => base64url(new TextEncoder().encode(JSON.stringify(value)));

const text = (value: unknown): string | null =>
  typeof value === "string" && value.length > 0 ? value : null;

function parseJwk(raw: string): Record<string, unknown> | null {
  const trimmed = raw.trim();
  if (!trimmed.startsWith("{")) return null;
  try {
    const parsed: unknown = JSON.parse(trimmed);
    return typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    throw new ProjectSigningKeyError("XOS_API_JWT_SIGNING_KEY looks like JSON but is not a JWK.");
  }
}

/**
 * Reads XOS_API_JWT_SIGNING_KEY. A private JWK gives ES256 or RS256 with its kid; anything else is a shared secret,
 * which production refuses. The error never quotes the value.
 */
export async function importProjectSigningKey(
  raw: string,
  options: { readonly production: boolean },
): Promise<ProjectSigningKey> {
  const jwk = parseJwk(raw);
  if (jwk === null) {
    if (options.production) {
      throw new ProjectSigningKeyError(
        "XOS_API_JWT_SIGNING_KEY is a shared secret; production signs only with a private JWK it imported as a JWT signing key (ADR 0168).",
      );
    }
    if (raw.length < 32) throw new ProjectSigningKeyError("The JWT signing key is too short.");
    const key = await crypto.subtle.importKey(
      "raw",
      new TextEncoder().encode(raw),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );
    return { alg: "HS256", kid: null, key };
  }
  const kid = text(jwk["kid"]);
  if (kid === null) {
    throw new ProjectSigningKeyError(
      "XOS_API_JWT_SIGNING_KEY has no kid; PostgREST finds the public key by it.",
    );
  }
  if (text(jwk["d"]) === null) {
    throw new ProjectSigningKeyError(
      "XOS_API_JWT_SIGNING_KEY is a public key; it needs the private part.",
    );
  }
  if (jwk["kty"] === "EC") {
    if (jwk["crv"] !== "P-256") {
      throw new ProjectSigningKeyError(
        "XOS_API_JWT_SIGNING_KEY must be on the P-256 curve (ES256).",
      );
    }
    const key = await crypto.subtle.importKey(
      "jwk",
      {
        kty: "EC",
        crv: "P-256",
        x: text(jwk["x"]) ?? "",
        y: text(jwk["y"]) ?? "",
        d: text(jwk["d"]) ?? "",
      },
      { name: "ECDSA", namedCurve: "P-256" },
      false,
      ["sign"],
    );
    return { alg: "ES256", kid, key };
  }
  if (jwk["kty"] === "RSA") {
    const part = (name: string) => text(jwk[name]) ?? "";
    const key = await crypto.subtle.importKey(
      "jwk",
      {
        kty: "RSA",
        n: part("n"),
        e: part("e"),
        d: part("d"),
        p: part("p"),
        q: part("q"),
        dp: part("dp"),
        dq: part("dq"),
        qi: part("qi"),
      },
      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
      false,
      ["sign"],
    );
    return { alg: "RS256", kid, key };
  }
  throw new ProjectSigningKeyError(
    "XOS_API_JWT_SIGNING_KEY must be an EC P-256 or an RSA private key.",
  );
}

/** A JWT over `claims`, signed with the key, its header naming the key's kid. */
export async function signProjectToken(
  claims: ProjectTokenClaims,
  signingKey: ProjectSigningKey,
): Promise<string> {
  const header =
    signingKey.kid === null
      ? { alg: signingKey.alg, typ: "JWT" }
      : { alg: signingKey.alg, typ: "JWT", kid: signingKey.kid };
  const head = `${encodeJson(header)}.${encodeJson(claims)}`;
  const data = new TextEncoder().encode(head);
  const algorithm =
    signingKey.alg === "ES256"
      ? { name: "ECDSA", hash: "SHA-256" }
      : signingKey.alg === "RS256"
        ? { name: "RSASSA-PKCS1-v1_5" }
        : { name: "HMAC" };
  // Web Crypto's ECDSA signature is r and s side by side, the form a JWS takes (RFC 7518, 3.4).
  const signature = await crypto.subtle.sign(algorithm, signingKey.key, data);
  return `${head}.${base64url(new Uint8Array(signature))}`;
}

/** A signer over one imported key, imported once. */
export function projectTokenSigner(
  raw: string,
  options: { readonly production: boolean },
): ProjectTokenSigner {
  let imported: Promise<ProjectSigningKey> | null = null;
  return async (claims) => {
    imported ??= importProjectSigningKey(raw, options);
    return signProjectToken(claims, await imported);
  };
}
